/* The overlay and results page use the same compact build-time index. */
(function(root){
  'use strict';
  const norm = s => String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  function edit(a,b){
    if(Math.abs(a.length-b.length)>2)return 3;
    const rows=Array.from({length:a.length+1},(_,i)=>[i]);rows[0]=Array.from({length:b.length+1},(_,j)=>j);
    for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++){
      rows[i][j]=Math.min(rows[i][j-1]+1,rows[i-1][j]+1,rows[i-1][j-1]+(a[i-1]===b[j-1]?0:1));
      if(i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])rows[i][j]=Math.min(rows[i][j],rows[i-2][j-2]+1);
    }
    return rows[a.length][b.length];
  }
  function score(r,q){const title=norm(r.title), text=norm([r.title,r.place,r.region,r.keywords,...r.water||[]].join(' ')), words=text.split(/[^a-z0-9]+/);let total=0;for(const term of norm(q).trim().split(/\s+/).filter(Boolean)){if(title.includes(term))total+=12;else if(text.includes(term))total+=5;else if(term.length>=4&&words.some(w=>edit(w,term)<=(term.length>6?2:1)))total+=2;else return -1;}return total;}
  const distance=(a,b)=>{const r=Math.PI/180, dlat=(b[1]-a[1])*r,dlon=(b[0]-a[0])*r,h=Math.sin(dlat/2)**2+Math.cos(a[1]*r)*Math.cos(b[1]*r)*Math.sin(dlon/2)**2;return 12742*Math.asin(Math.min(1,Math.sqrt(h)));};
  if(typeof module!=='undefined')module.exports={score,edit,distance};
  if(typeof document==='undefined')return;
  const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let pending, records=[], nearby=null;
  function load(){return pending ||= fetch('/assets/search-index.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(r=>records=r).catch(e=>{pending=null;throw e;});}
  function recent(){try{return JSON.parse(localStorage.getItem('castward.searches')||'[]').filter(x=>typeof x==='string').slice(0,5);}catch{return [];}}
  function remember(q){if(!q.trim())return;try{localStorage.setItem('castward.searches',JSON.stringify([q.trim(),...recent().filter(x=>x!==q.trim())].slice(0,5)));}catch{}}
  function ranked(q){return records.map(r=>({r,s:score(r,q)})).filter(x=>x.s>=0&&(!nearby||x.r.coordinates)).sort((a,b)=>nearby?distance(nearby,a.r.coordinates)-distance(nearby,b.r.coordinates):b.s-a.s).map(x=>x.r);}
  const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  function card(r,small=false){return `<a class="${small?'search-hit':'search-card'}" href="${esc(r.url)}"><img src="${esc(r.image)}" alt="" loading="lazy" width="640" height="400"><span class="search-card-copy"><small>${esc(r.type)}${r.place?' / '+esc(r.place):''}</small><${small?'strong':'h2'}>${esc(r.title)}</${small?'strong':'h2'}><span>${esc(r.water?.join(' · ')||r.region||'A little knowledge for the next trip')}${nearby&&r.coordinates?' · '+Math.round(distance(nearby,r.coordinates))+' km away':''}</span>${!small&&r.type==='Trips'?'<em>'+esc(r.months.length?r.months.map(m=>months[m-1]).join(' · '):'Season: ask locally')+'</em>':''}</span><b aria-hidden="true">↗</b></a>`;}
  async function locate(status, render){if(!navigator.geolocation){status.textContent='Location is unavailable. Try a place name.';return;}status.textContent='Allow location access to find nearby trips.';navigator.geolocation.getCurrentPosition(async p=>{nearby=[p.coords.longitude,p.coords.latitude];try{await load();render();}catch{status.textContent='Search is unavailable. Please try again.';}},()=>status.textContent='Location is unavailable. Try a place name.',{timeout:10000,maximumAge:300000});}
  const dialog=document.querySelector('#search-dialog'), input=document.querySelector('#header-search');
  if(dialog&&input){
    const tray=document.createElement('div');tray.className='search-tray';tray.innerHTML='<div class="search-suggestions"></div><p class="search-status" role="status"></p><div class="search-instant"></div><a class="search-all" href="/search/">Explore all results ↗</a><p class="search-key-hint">↑ ↓ to move · Enter to open · Esc to close</p>';dialog.append(tray);
    input.setAttribute('aria-controls','instant-results');const results=tray.querySelector('.search-instant');results.id='instant-results';const status=tray.querySelector('.search-status');let generation=0,active=-1;
    function suggestions(){tray.querySelector('.search-suggestions').innerHTML='<span>POPULAR</span>'+['Alaska','Tarpon','Fly fishing','Weather'].map(q=>`<button type="button" data-query="${q}">${q}</button>`).join('')+'<button type="button" data-search-near>◎ Near me</button>'+(recent().length?'<span>RECENT</span>'+recent().map(q=>`<button type="button" data-query="${esc(q)}">${esc(q)}</button>`).join('')+'<button type="button" data-clear-recent>Clear recent</button>':'');}
    async function render(){const run=++generation;active=-1;status.textContent='Find a little inspiration…';try{await load();if(run!==generation)return;const q=input.value.trim(),all=ranked(q), chosen=q||nearby?all.slice(0,10):['Trips','Waters','Guides','Species','Lingo','Tools'].flatMap(type=>all.filter(r=>r.type===type).slice(0,1));results.innerHTML=['Trips','Waters','Guides','Species','Lingo','Tools'].map(type=>{const group=chosen.filter(r=>r.type===type);return group.length?`<section><h3>${type}</h3>${group.map(r=>card(r,true)).join('')}</section>`:'';}).join('');status.textContent=all.length?(q?`${all.length} places to start`:'A few good places to start'):'No luck yet. Try a nearby town, a fish name or fewer words.';tray.querySelector('.search-all').href='/search/?q='+encodeURIComponent(q);tray.querySelector('.search-all').textContent='See all '+all.length+' results ↗';}catch{status.innerHTML='Search could not load. <button type="button" data-search-retry>Try again</button>';}}
    dialog.addEventListener('click',e=>{const q=e.target.closest('[data-query]');if(q){nearby=null;input.value=q.dataset.query;input.focus();render();}if(e.target.closest('[data-clear-recent]')){try{localStorage.removeItem('castward.searches');}catch{}suggestions();}if(e.target.closest('[data-search-near]'))locate(status,render);if(e.target.closest('[data-search-retry]'))render();if(e.target.closest('.search-hit,.search-all'))remember(input.value);});
    input.addEventListener('input',()=>{nearby=null;render();});dialog.querySelector('form').addEventListener('submit',()=>remember(input.value));
    dialog.addEventListener('keydown',e=>{const links=[...results.querySelectorAll('a')];if(['ArrowDown','ArrowUp'].includes(e.key)&&links.length){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+links.length)%links.length;links.forEach((a,i)=>a.classList.toggle('active',i===active));links[active].focus();}if(e.key==='Enter'&&e.target===input&&active>=0){e.preventDefault();links[active].click();}});
    new MutationObserver(()=>{if(dialog.open){suggestions();render();}}).observe(dialog,{attributes:true,attributeFilter:['open']});
    document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.target.closest('input,textarea,select,[contenteditable=true]')){e.preventDefault();if(!dialog.open)dialog.showModal();input.focus();}});
  }
  const page=document.querySelector('.search-page');
  if(page){const field=page.querySelector('#page-search'),status=page.querySelector('.search-count'),grid=page.querySelector('.search-grid'),filters=[...page.querySelectorAll('[data-filter]')],params=new URLSearchParams(location.search);let limit=24;field.value=params.get('q')||'';
    function render(){const q=field.value.trim(), found=ranked(q).filter(r=>filters.every(f=>!f.value||(f.dataset.filter==='month'?r.months.includes(Number(f.value)):f.dataset.filter==='water'?r.water.includes(f.value):r[f.dataset.filter]===f.value)));status.textContent=found.length+' results'+(nearby?' · Nearest trips first':'')+(q?' for “'+q+'”':'');grid.innerHTML=found.length?found.slice(0,limit).map(r=>card(r)).join(''):'<div class="search-empty"><span>NO BITES YET</span><h2>Try another stretch.</h2><p>Clear a filter or try a broader place name. Month filters show documented seasons only.</p><a href="/trips/">Browse every trip ↗</a></div>';page.querySelector('[data-search-more]').hidden=found.length<=limit;const state=new URLSearchParams();if(q)state.set('q',q);filters.forEach(f=>{if(f.value)state.set(f.dataset.filter,f.value);});history.replaceState(null,'','/search/'+(state.size?'?'+state:''));}
    function start(){status.textContent='Find your next day outside…';load().then(()=>{filters.forEach(f=>{const key=f.dataset.filter,values=key==='month'?months.map((v,i)=>[i+1,v]):[...new Set(records.flatMap(r=>key==='water'?r.water:r[key]).filter(Boolean))].sort().map(v=>[v,v]);f.innerHTML=f.options[0].outerHTML+values.map(([v,label])=>`<option value="${esc(v)}">${esc(label)}</option>`).join('');f.value=params.get(key)||'';});render();}).catch(()=>status.innerHTML='Search could not load. <button type="button" data-search-retry>Try again</button>');}
    page.querySelector('form').onsubmit=e=>{e.preventDefault();remember(field.value);render();};field.oninput=()=>{limit=24;nearby=null;render();};filters.forEach(f=>f.onchange=()=>{limit=24;render();});page.querySelector('[data-search-near]').onclick=()=>locate(status,render);page.querySelector('[data-search-clear]').onclick=()=>{nearby=null;field.value='';filters.forEach(f=>f.value='');limit=24;render();};page.querySelector('[data-search-more]').onclick=()=>{limit+=24;render();};page.addEventListener('click',e=>{if(e.target.closest('[data-search-retry]'))start();if(e.target.closest('.search-card'))remember(field.value);});start();
  }
})(typeof window==='undefined'?globalThis:window);
